namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilizations." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented programming basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS201", Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm design and computational complexity. He previously worked at Google Research before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Title = "Machine Learning", CourseCode = "CS450", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and practical applications using Python.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel is a leading researcher in applied machine learning with publications in NeurIPS and ICML. She consults for several AI startups.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Title = "Calculus I", CourseCode = "MATH101", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a focus on making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Title = "Linear Algebra", CourseCode = "MATH202", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos researches numerical linear algebra and its applications in scientific computing.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Title = "Classical Mechanics", CourseCode = "PHYS201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and rigid body dynamics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park's research focuses on theoretical mechanics and astrophysics. He is the author of two widely-used textbooks.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 7, Title = "Quantum Physics", CourseCode = "PHYS301", Description = "Introduction to quantum mechanics: wave-particle duality, Schrödinger equation, angular momentum, and hydrogen atom.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang is an experimental physicist whose research involves quantum computing and quantum information theory.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 8, Title = "Creative Writing", CourseCode = "ENG210", Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Michael O'Brien", InstructorBio = "Prof. O'Brien is a published novelist and poet. His works have appeared in The New Yorker and The Atlantic.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 9, Title = "American Literature", CourseCode = "ENG301", Description = "Survey of American literature from the colonial period to the present, including major works and literary movements.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Angela Foster", InstructorBio = "Dr. Foster specializes in 20th-century American fiction and has published a critically acclaimed study of the Harlem Renaissance.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 10, Title = "World History: 1500 to Present", CourseCode = "HIST102", Description = "Global perspectives on major historical developments from the early modern period to contemporary times.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is a historian of global trade networks and cultural exchange. He has conducted fieldwork on four continents.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.Find(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.Find(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database
        return GetCourse(request.CourseId) is not null;
    }
}

